// QuoteRequestStatusResponse Response to GET /v1/payments/quote-requests/{quoteRequestId}. The `status` enum describes
// the quote-request batch lifecycle and is disjoint from the payment-status enum.
type QuoteRequestStatusResponse struct {
	// DeclineSummary Why the request drew few or no quotes, so a caller can tell "nobody can fund this right
	// now" from "my request was malformed".
	//
	// EXHAUSTIVE over agents: every agent that declined is counted exactly once, under its most
	// recent reason, so the counts sum to the number of agents that declined. An agent that
	// declined more than once with different reasons is counted once, not once per reason.
	//
	// Empty means nobody declined. ABSENT means the auction detail could not be read, so the
	// breakdown is unknown. While `status` is `collecting` it is provisional, because agents are
	// still responding. When the gateway can tell why no settler was asked, `error` says why.
	//
	// The free-form decline detail is never relayed, because that detail carries an agent's
	// balances and would let a caller map inventory by polling cheap quote-requests across
	// corridors.
	DeclineSummary *[]DeclineSummaryEntry `json:"decline_summary,omitempty"`

	// Error Why the request has no quotes, when no settler was asked and the gateway can tell why.
	// Present only on a closed request with an empty `quotes` array:
	//
	// - `NO_SETTLER_FOR_CORRIDOR`: no settler serves this source and destination pair, and
	//   `requested_count` is 0.
	// - `SERVICE_BUSY`: no capacity was available to start the auction.
	//
	// Absent in every other case: while `status` is `collecting`; whenever a settler was
	// asked (read `decline_summary` then); and when `requested_count` is absent for any reason
	// other than `SERVICE_BUSY`, because whether a settler serves the pair is then unknown.
	// `retry_classification` says what to do next.
	Error *PaymentFailure `json:"error,omitempty"`

	// Payments Flat list of awarded (quote_id, payment_id) pairs. At most one entry under MVP single-award.
	Payments       *[]AwardedPayment `json:"payments,omitempty"`
	QuoteRequestId string            `json:"quote_request_id"`

	// Quotes Collected quotes with award linkage — those collected so far while `collecting`, the full set once the window closes.
	Quotes *[]AwardedQuote `json:"quotes,omitempty"`

	// RequestedCount How many agents the request was broadcast to. The only auction count that is not
	// derivable from the rest of this response:
	//
	// - quoted = `quotes` length
	// - declined = sum of `decline_summary[].count`
	// - participated = quoted + declined
	// - silent = `requested_count` - participated
	//
	// Silence and a decline are different signals, which is why the denominator is surfaced
	// rather than left implicit.
	//
	// ABSENT when the number is unknown, which happens when the broadcast count was never
	// recorded or when the auction detail could not be read. Absence means unknown, never zero,
	// so `silent` is derivable only when this field is present.
	RequestedCount *int `json:"requested_count,omitempty"`

	// Status Derived batch lifecycle, computed at read time (not a stored state machine). Disjoint
	// from the payment-status enum returned by the award and payment-status endpoints.
	// - `collecting` — collection window still open; `quotes` lists those collected so far
	//   (a quote is awardable from arrival, by its own `award_deadline`; more may arrive until
	//   `collection_close`).
	// - `ready` — collection complete; none awarded yet; either at least one quote is still
	//   within its `award_deadline`, or no settler bid (empty `quotes` array — the successful
	//   "no quotes available" result). When the gateway can tell why no settler was asked,
	//   `error` says why.
	// - `awarded` — a quote produced a payment row; no further awards accepted (MVP).
	// - `expired` — collection closed, nothing awarded, and every collected quote is now past
	//   its `award_deadline` ("quotes lapsed"). An empty batch is `ready`, not `expired` — the
	//   two are deliberately distinct ("no quotes available" vs "quotes lapsed").
	Status QuoteRequestStatusResponseStatus `json:"status"`
}

