// RefundSignature The refund authorization for a `refund_available` payment, as the verifier signed it.
// Submit it to the source chain's escrow `refund` to return your funds yourself.
//
// Anyone holding it can submit the refund, but the escrow only ever pays the depositor. If
// the settler delivers late and is paid first, the refund no longer goes through.
// On Solana the submitter also receives the rent of the deposit account the refund closes.
type RefundSignature struct {
	// MessageHash The signed digest, hex without the `0x` prefix.
	MessageHash string `json:"message_hash"`

	// MessagePrehash The signed message as JSON. On EVM and Tron chains it carries the RefundWitness the
	// escrow's `refund` takes.
	MessagePrehash string `json:"message_prehash"`

	// Signature The verifier's signature over `message_hash`. Hex with the `0x` prefix on EVM and
	// Tron chains, hex without it on Solana.
	Signature string `json:"signature"`
}

// ReserveAuth The reserve message naming the chosen quote's settler, signed by the quote request's
// `quote_selector`. The escrow verifies it on chain against the `reserver` that
// `sender_auth` names. It binds the deposit, the chosen quote's `quote_id`, the quote's
// `settler_address` and its `source_amount`.
//
//   - EVM and Tron: the message is the escrow's reserve witness, `{depositId, quoteHash,
//     settler, sourceAmount}`. The deposit id is derived from the signed `sender_auth`,
//     `keccak256(abi.encode(depositor, signature, nonce))` over the Permit2 signature and
//     nonce, so sign `reserve_auth` after `sender_auth`. `message_prehash` is the witness as
//     typed data (EIP-712, TIP-712 on Tron), a JSON string `{domain, types, primaryType,
//     message}` with `primaryType` `ReserveWitness`. The domain is `name` `Escrow`, `version`
//     `3`, `chainId` as 0x-prefixed hex without leading zeros (its lower 32 bits on Tron) and
//     `verifyingContract` the escrow, with no other member except an empty `salt`. Addresses
//     are 0x-prefixed hex, on Tron too, and `sourceAmount` is a decimal string. `message` is
//     the typed data's digest, and `signature` the `quote_selector`'s signature over it. A
//     contract wallet signs as it does for ERC-1271.
//   - Solana: `message` is the escrow's reserve message hash, which binds the settler, the
//     deposit hash that `sender_auth` signs, the quote hash and the source amount. None of
//     these depends on the deposit signature, so the two can be signed in either order.
//     `message_prehash` is the reserve record as a JSON string, `{deposit_hash, recipient,
//     quote_hash, source_amount}`: the hashes as 0x-prefixed hex, `recipient` the settler's
//     base58 address and `source_amount` a decimal string. `signature` is the
//     `quote_selector`'s Ed25519 signature over `message`, so `quote_selector` must be a key
//     that can sign.
//   - Stellar: `message` is the escrow's reserve digest, which binds the settler, the deposit
//     id (the deposit digest that `sender_auth` signs), the quote hash and the source amount.
//     None of these depends on the delegate's signature, so the two can be signed in either
//     order. `message_prehash` is the reserve record as a JSON string, `{deposit_id,
//     quote_hash, settler, source_amount}`: the hashes as 0x-prefixed hex, `settler` a `G...`
//     or `C...` address and `source_amount` a decimal string. `signature` is the
//     `quote_selector`'s Ed25519 signature over `message`, so `quote_selector` must be a
//     `G...` account whose key can sign.
type ReserveAuth struct {
	// Message The 0x-prefixed 32-byte digest that `signature` signs, on every chain.
	Message string `json:"message"`

	// MessagePrehash The signed reserve, as a JSON string: the typed data on EVM and Tron, the reserve
	// record on Solana and Stellar, as described above.
	MessagePrehash string `json:"message_prehash"`

	// Signature The `quote_selector`'s signature over `message`, 0x-prefixed hex on every chain.
	Signature string `json:"signature"`
}

